entries[466376] = { ["name"] = "Oberhaupt", ["text"] = "Sofort\nMug und Zee wechseln sich als Oberhaupt ab. Immer, wenn alle Spielercharaktere sich entweder auf Mugs oder Zees Seite des Raumes befinden, übernimmt dieser Kopf die Führung, verbraucht 10 Stapel von 'Mumm' und verleiht Mug'Zee eine einzigartige Reihe an Fähigkeiten.\n\nWenn Mug die Kontrolle übernimmt, entfesselt er außerdem ' Elementares Blutbad '. Wenn Zee die Kontrolle übernimmt, beginnt er seinen Angriff mit ' Unkontrollierte Zerstörung '." }
