entries[466671] = { ["name"] = "Schrottfeld 9001", ["text"] = "Bei unter 60% Gesundheit entsteht ein schützender Schrottvortex um Euch, der den erlittenen Schaden entweder 15 Sek. lang, oder bis 3251 Schaden verhindert wurden, um 50% verringert. Dieser Effekt kann nur alle 30 Sek. auftreten.\n\nNachdem das Schrottfeld im Kampf 20 Sek. lang nicht aktiviert wurde, überlädt es und erhöht Euer Tempo 12 Sek. lang um 113 .\nGilt nur für Tankspezialisierungen." }
