entries[466990] = { ["name"] = "Vernichtendes Feuer", ["text"] = "Tierherrschaft\nWährend 'Ruf der Wildnis' aktiv ist, ergebt Ihr Euch der Dunkelheit, die Euch alle 4 Sek. 'Vernichtendes Feuer' und 'Todesstoß' gewährt.\n\nVernichtendes Feuer\nDer Einsatz von 'Schwarzer Pfeil' lässt Euch zusätzlich eine Salve aus 2 weiteren Einsätzen von 'Schwarzer Pfeil' mit einer Effektivität von 50% auf Ziele in der Nähe abfeuern. Dabei werden Gegner priorisiert, die nicht vom regelmäßigen Schadenseffekt von 'Schwarzer Pfeil' betroffen sind.\n\nTreffsicherheit\nWährend 'Volltreffer' aktiv ist, ergebt Ihr Euch der Dunkelheit, die Euch 'Vernichtendes Feuer' und 'Todesstoß' gewährt.\n\nVernichtendes Feuer\nDer Einsatz von 'Schwarzer Pfeil' lässt Euch zusätzlich eine Salve aus 2 weiteren Einsätzen von 'Schwarzer Pfeil' mit einer Effektivität von 50% auf Ziele in der Nähe abfeuern. Dabei werden Gegner priorisiert, die nicht vom regelmäßigen Schadenseffekt von 'Schwarzer Pfeil' betroffen sind." }
entries[466991] = { ["name"] = "Vernichtendes Feuer", ["text"] = "Sofort\nTierherrschaft\nWährend 'Ruf der Wildnis' aktiv ist, ergebt Ihr Euch der Dunkelheit, die Euch alle 4 Sek. 'Vernichtendes Feuer' und 'Todesstoß' gewährt.\n\nVernichtendes Feuer\nDer Einsatz von 'Schwarzer Pfeil' lässt Euch zusätzlich eine Salve aus 2 weiteren Einsätzen von 'Schwarzer Pfeil' mit einer Effektivität von 50% auf Ziele in der Nähe abfeuern. Dabei werden Gegner priorisiert, die nicht vom regelmäßigen Schadenseffekt von 'Schwarzer Pfeil' betroffen sind.\n\nTreffsicherheit\nWährend 'Volltreffer' aktiv ist, ergebt Ihr Euch der Dunkelheit, die Euch 'Vernichtendes Feuer' und 'Todesstoß' gewährt.\n\nVernichtendes Feuer\nDer Einsatz von 'Schwarzer Pfeil' lässt Euch zusätzlich eine Salve aus 2 weiteren Einsätzen von 'Schwarzer Pfeil' mit einer Effektivität von 50% auf Ziele in der Nähe abfeuern. Dabei werden Gegner priorisiert, die nicht vom regelmäßigen Schadenseffekt von 'Schwarzer Pfeil' betroffen sind." }
