entries[467021] = { ["name"] = "Klauenzorn", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nDer Zaubernde verfällt in Raserei und fügt dem gegnerischen Ziel 3.4 Sek. lang alle 0.5 Sek. körperlichen Schaden zu." }
entries[467024] = { ["name"] = "Kaja'Cola-Träger", ["text"] = "Verlegte Kuriositäten haben jetzt einmal pro Tiefe eine Chance von 35%, 1 Kaja'Colas zu enthalten, und Brann beschwört jetzt ein Sechserpack Kaja'Cola, wenn er ein Lagerfeuer macht.\n\nEs gibt verschiedene Kaja'Cola-Geschmacksrichtungen und jede hat einen eigenen Effekt, der beim Einsammeln wirkt." }
entries[467026] = { ["name"] = "Goblomagnetische Hüpfgranate", ["text"] = "Brann hat eine Chance, im Kampf eine goblomagnetische Hüpfgranate auf ein Ziel zu werfen, die mäßigen Naturschaden verursacht und eine Chance von 20% hat, das Ziel für 1.5 Sek. zu betäuben. Anschließend besteht eine Chance von 25%, dass die Granate zu einem neuen Ziel hüpft.\n\nDie Granate kann bedenkenlos zu Gruppenmitgliedern springen." }
entries[467029] = { ["name"] = "Einschlagsumwandlungsmatrix", ["text"] = "Zu Kampfbeginn aktiviert Brann für 10 Sek. die Umwandlungsmatrix. Ein kleiner Anteil von sämtlichem Schaden, den die Gruppe währenddessen verursacht, erhöht den Primärwert. Die Erhöhung wird unter den Gruppenmitgliedern aufgeteilt.\n\nWenn sich die Umwandlungsmatrix deaktiviert, bleibt die Erhöhung des Primärwerts noch 10 Sek. lang bestehen. Dieser Effekt kann nur einmal alle 2 Min. auftreten." }
entries[467031] = { ["name"] = "Schwarzblutstrom", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchwarzblut rinnt vom Fabrikdach und verursacht alle 0.5 Sek. 14 Schattenschaden." }
entries[467032] = { ["name"] = "Eierfeuer" }
entries[467033] = { ["name"] = "B3U13RÄUB-R", ["text"] = "Tastet die Umgebung alle 60 Sek. oder 5 Sek. nach Kampfbeginn ab, hebt verlegte Kuriositäten hervor und lässt Gegner mit weniger als 95% Gesundheit 10 Sek. lang 4% mehr Schaden erleiden." }
entries[467034] = { ["name"] = "Rückentwickelte Goblintodesbombe", ["text"] = "Wenn die Gesundheit eines Spielcharakters während eines Kampfes unter 50% fällt, wirft Brann eine riesige Bombe, die beim Einschlag explodiert.\n\nDie Explosion stößt umstehende Gegner zurück, verlangsamt sie 5 Sek. lang um 45% und heilt Gruppenmitglieder in der Nähe um 35% ihrer maximalen Gesundheit. Kann nur einmal alle 1.5 Min. auftreten." }
entries[467035] = { ["name"] = "Absurd großer Magnet", ["text"] = "Wenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 100%, weggeworfene Panzerung zu magnetisieren. Diese Panzerung haftet an Gruppenmitgliedern und gewährt ihnen 5% ihrer maximalen Gesundheit als Schild, der sich außerhalb des Kampfes regeneriert.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
entries[467036] = { ["name"] = "Raketenausrüstung mit Biotreibstoff", ["text"] = "Gruppenmitglieder werden mit Raketenausrüstung mit Biotreibstoff ausgerüstet.\n\nBiotreibstoff\nJeder getötete Gegner füllt die Raketenausrüstung mit Biotreibstoff auf und erhöht damit 10 Sek. lang die Bewegungsgeschwindigkeit um 2% und das Tempo um 2%. Bis zu 10-mal stapelbar." }
entries[467037] = { ["name"] = "Angeklopfter Erweiterungschip", ["text"] = "Branns maximale Gesundheit ist um 4% erhöht und er verursacht 20% mehr Schaden und Heilung.\n\nIm Kampf kann Brann von mechanischen Robotern anvisiert werden, die sich zerstören oder vertreiben lassen. Wenn sie Brann erreichen, erleidet er 30% seiner maximalen Gesundheit als Schaden und wird für 5 Sek. betäubt." }
