entries[467297] = { ["name"] = "Statischer Schock", ["text"] = "200 Meter Reichweite\nSofort\nEin Stoß von Elektrizität bricht aus zusammenstoßenden Spielercharakteren hervor, wenn beide von ' Defekter Schocker ' betroffen sind, und fügt allen Spielercharakteren 2096272 Naturschaden zu.\n\nDieser unterbrechende Blitz entfernt ' Rückkopplungsneutralisator ' von Verstärkern innerhalb von 8 Metern." }
