entries[467306] = { ["name"] = "Lebhafte Totems", ["text"] = "[ Verstärkung : 'Lavapeitsche' hat eine Chance, ein Totem der Verbrennung zu beschwören, das 'Sengende Blitze' schleudert, die Gegnern in der Nähe (65.205% der Zaubermacht) Feuerschaden zufügen. Hält 8 Sek. lang an.\n\n'Frostschocks', die durch 'Hagelsturm', 'Lavapeitsche' oder 'Feuernova' ermächtigt wurden, lassen Eure 'Totems der Verbrennung' eine 'Verbrennende Salve' auf bis zu 5 Gegner in der Nähe schleudern, die (92.736% der Zaubermacht) Feuerschaden verursacht /\n\nWiederherstellung\nWenn Ihr ein 'Totem der Heilungsflut', 'Totem des heilenden Flusses', 'Totem des Wolkenbruchs', oder 'Totem der Geistverbindung' beschwört, zaubert Ihr einen kostenlosen Spontanzauber von 'Kettenheilung' mit 100% Effektivität ]" }
entries[467307] = { ["name"] = "Tritt des aufziehenden Windes", ["text"] = "2.5% von Grundmana\nSofort 10 sek. Abklingzeit\nNebelwirker ( Nebelwirkermönch )\nErzeugt einen starken Windstoß, der Gegnern vor Euch in einem kegelförmigen Bereich von 25 Metern (179.75% der Angriffskraft) Naturschaden zufügt, der gleichmäßig auf sie verteilt wird. Der Schaden erhöht sich um 6% für jedes getroffene Ziel, bis zu 30%.\n\nGewährt 4 Sek. lang 'Rauschende Winde', wodurch die Heilung von 'Erneuernder Nebel' um 200% erhöht wird.\n\nErzeugt einen starken Windstoß, der Gegnern vor Euch in einem kegelförmigen Bereich von 25 Metern (179.75% der Angriffskraft) Naturschaden zufügt, der gleichmäßig auf sie verteilt wird. Der Schaden erhöht sich um 6% für jedes getroffene Ziel, bis zu 30%.\n\nGewährt 4 Sek. lang 'Rauschende Winde', wodurch die Heilung von 'Erneuernder Nebel' um 200% erhöht wird." }
