entries[468019] = { ["name"] = "Phantomschmerz", ["text"] = "100 Meter Reichweite\nSofort\nTreffsicherheit\nWenn 'Gezielter Schuss' Schaden verursacht, werden 15% des verursachten Schadens auf bis zu 8 andere Einheiten repliziert, die vom regelmäßigen Schaden von 'Schwarzer Pfeil' betroffen sind.\n\nTierherrschaft\nWenn 'Tötungsbefehl' Schaden verursacht, werden 15% des verursachten Schadens auf bis zu 8 andere Einheiten repliziert, die vom regelmäßigen Schaden von 'Schwarzer Pfeil' betroffen sind." }
entries[468021] = { ["name"] = "Direkte Verbindung", ["text"] = "Sofort\nBelegt 2 Spielercharaktere mit 'Direkte Verbindung'. 'Direkte Verbindung' fügt allen Spielercharakteren im Umkreis von 12 Metern 10 Sek. lang alle 1 Sek. 263 Naturschaden zu." }
