entries[468033] = { ["name"] = "Sturmgebundene Rune des Runenmagiers", ["text"] = "Alle 6 Sek. im Kampf wird die Rune überladen und trifft einen Gegner in der Nähe mit einem Blitz, der 187 Naturschaden verursacht.\n\nDieser Effekt wird sofort ausgelöst, wenn eine Kreatur zum ersten Mal getroffen wird." }
entries[468034] = { ["name"] = "Kugel des Nachtflutwellenbeugers", ["text"] = "Ca. 4 Procs pro Minute\nEure Distanzzauber und -fähigkeiten haben eine Chance, einen Batzen Wasser auf einen Gegner zu schleudern, der diesem sowie vier weiteren Gegnern innerhalb von 7 Metern um ihn 259 Frostschaden zufügt." }
entries[468035] = { ["name"] = "Verfluchter Piratenschädel", ["text"] = "Ca. 3 Procs pro Minute\nEure Nahkampfangriffe haben eine Chance, eine Blutnova aufzurühren, die 5 Gegnern innerhalb von 5 Metern um Euch 8 Sek. lang pro Sekunde 52 Schattenschaden zufügt." }
entries[468037] = { ["name"] = "Schwarzer Pfeil", ["text"] = "40 Meter Reichweite\nSofort\nTierherrschaft\nWährend 'Ruf der Wildnis' aktiv ist, ergebt Ihr Euch der Dunkelheit, die Euch alle 4 Sek. 'Vernichtendes Feuer' und 'Todesstoß' gewährt.\n\nVernichtendes Feuer\nDer Einsatz von 'Schwarzer Pfeil' lässt Euch zusätzlich eine Salve aus 2 weiteren Einsätzen von 'Schwarzer Pfeil' mit einer Effektivität von 50% auf Ziele in der Nähe abfeuern. Dabei werden Gegner priorisiert, die nicht vom regelmäßigen Schadenseffekt von 'Schwarzer Pfeil' betroffen sind.\n\nTreffsicherheit\nWährend 'Volltreffer' aktiv ist, ergebt Ihr Euch der Dunkelheit, die Euch 'Vernichtendes Feuer' und 'Todesstoß' gewährt.\n\nVernichtendes Feuer\nDer Einsatz von 'Schwarzer Pfeil' lässt Euch zusätzlich eine Salve aus 2 weiteren Einsätzen von 'Schwarzer Pfeil' mit einer Effektivität von 50% auf Ziele in der Nähe abfeuern. Dabei werden Gegner priorisiert, die nicht vom regelmäßigen Schadenseffekt von 'Schwarzer Pfeil' betroffen sind." }
entries[468040] = { ["name"] = "Triumphales Säckchen geschnitzter Lorenhallwappen", ["text"] = "Wirken in 1.5 sek. 1.5 sek. Abklingzeit\nSammelt 15 geschnitzte Lorenhallwappen." }
entries[468045] = { ["name"] = "Festtagsbündel runenverzierter Lorenhallwappen", ["text"] = "Wirken in 1.5 sek. 1.5 sek. Abklingzeit\nSammelt 15 runenverzierte Lorenhallwappen." }
